def prime_factorization(n):
    factors = {}
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1
    return factors

def tau_n_pow_12(n):
    if n == 1:
        # tau(1^12) = tau(1) = 1. n=1 is not in the required set, but good practice.
        return 1

    factors = prime_factorization(n)

    # tau(n^12) = product (12 * a_i + 1) for each prime factor p_i^a_i of n
    tau_val = 1
    for prime, exponent in factors.items():
        tau_val *= (12 * exponent + 1)
    return tau_val

test_cases = [6, 10, 12, 14, 15, 18, 20, 24, 25]
results = {}

print("Testing n = tau(n^12) for composite n:")
for n in test_cases:
    tau_val = tau_n_pow_12(n)
    is_solution = (n == tau_val)
    results[n] = {'tau_val': tau_val, 'is_solution': is_solution}
    print(f"n={n}: tau(n^12) = {tau_val}. Check (n = tau(n^12)): {is_solution}")

# Prepare results for writing to notes
output = "\n--- Computational Results ---\n"
